# The CFA is 16-byte aligned, but the frame pointer that the CFI uses to describe it isn't, as in code
# generated by the .NET JIT: s0 points 8 bytes above the bottom of the frame.
    .text
    .globl _start
    .type _start, @function
_start:
    .cfi_startproc
    .cfi_undefined ra
    call    foo
    li      a0, 0
    li      a7, 93
    ecall
    .cfi_endproc

    .type foo, @function
foo:
    .cfi_startproc
    addi    sp, sp, -16
    .cfi_def_cfa_offset 16
    sd      ra, 8(sp)
    sd      s0, 0(sp)
    .cfi_offset ra, -8
    .cfi_offset s0, -16
    addi    s0, sp, 16
    .cfi_def_cfa s0, 0
    call    bar
    ld      ra, 8(sp)
    ld      s0, 0(sp)
    addi    sp, sp, 16
    ret
    .cfi_endproc

    .type bar, @function
bar:
    .cfi_startproc
    addi    sp, sp, -32
    .cfi_def_cfa_offset 32
    sd      ra, 24(sp)
    sd      s0, 16(sp)
    .cfi_offset ra, -8
    .cfi_offset s0, -16
    addi    s0, sp, 8
    .cfi_def_cfa s0, 24
.Lbar_crash:
    sd      zero, 0(zero)
    ld      ra, 24(sp)
    ld      s0, 16(sp)
    addi    sp, sp, 32
    ret
    .cfi_endproc

    .section .note.ABI-tag, "a"
    .p2align 2
    .long 4, 16, 1
    .asciz "GNU"
    .long 0, 3, 2, 0
